// Demo: Foundation drill - label the seven pillars of the Signature Linker on a blank d
(function(){'use strict';
var DATA={"label": "Foundation drill - label the seven pillars of the Signature ", "expr": "(6+7)*5"};

var s=DATA.expr,pos=0;
function peek(){return s[pos];}
function num(){var st=pos;while(pos<s.length&&/[0-9.]/.test(s[pos]))pos++;
  return parseFloat(s.slice(st,pos));}
function factor(){if(peek()==='('){pos++;var v=expr();pos++;return v;}return num();}
function term(){var v=factor();while(peek()==='*'||peek()==='/'){var op=s[pos++];var r=factor();
  v=op==='*'?v*r:v/r;}return v;}
function expr(){var v=term();while(peek()==='+'||peek()==='-'){var op=s[pos++];var r=term();
  v=op==='+'?v+r:v-r;}return v;}
var result=expr();
console.log('Expression ('+DATA.label+'): '+DATA.expr);
console.log('Result = '+result);
})();

